TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3"},{"id":"R4","met":"yes","where":"Question 4"},{"id":"R5","met":"partial","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"partial","where":"References"}],"technical_issues":[{"where":"Question 3(b)","issue":"0.00699 × 720 is about 5.03 hours, not 3.5 hours."},{"where":"Question 3(c)","issue":"End-to-end availability ignores the other components. The correct value is about 0.99301 × 0.999975 ≈ 99.30%, not 99.9975%."},{"where":"Question 4","issue":"Circuit breaker states are misnamed. Failures should move the breaker to Open, not Closed, and Open should be the state that fails fast."},{"where":"Question 5","issue":"Stating that partition tolerance is given up is wrong for a distributed payment system. The payment answer should choose consistency over availability during a partition and name a technique such as idempotency keys or sagas."},{"where":"Question 1","issue":"The availability response measure ('stay up most of the time') is not quantified, for example as a percentage or a p95 error rate."},{"where":"References","issue":"Reference [2] is cited in Question 4 but missing from the reference list. No assumptions are stated, for example that failures are independent."}],"overall":"Sound choices on the modular monolith and the performance attribute, but Question 3 has two incorrect parts (downtime arithmetic and end-to-end availability). The circuit breaker states are swapped, the CAP reasoning for payments is wrong, and reference [2] is missing. The ADR lacks a negative consequence and assumptions are not stated.","criteria":[{"id":"C1","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"Performance and availability are sensibly chosen and justified from the lunch-hour scenario. The performance scenario is complete and measurable (p95 under 1.5 s). The availability response measure ('stay up most of the time') is not measurable, so the scenarios fall short of Excellent.","evidence":[{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":5.0,"scale":6.0,"points":5.0,"max":6.0,"reasoning":"Clear modular-monolith recommendation. Trade-offs are tied to the scenario: a five-developer team against eight to ten services, and the single-VM and deployment-downtime problems. The downside of independent scaling and shared-process failure is acknowledged.","evidence":[{"where":"Question 2","quote":"The slow lunchtime responses come from running on a single virtual machine"}]},{"id":"C3","level":"Developing","mark":3.0,"scale":8.0,"points":3.0,"max":8.0,"reasoning":"Part (a) is correct at 99.30%. Part (b) is an arithmetic error: 0.00699 × 720 is about 5.0 hours, not 3.5. Part (c) is wrong because it ignores the other components and reports 99.9975% as the end-to-end figure rather than about 99.30%. Two parts are incorrect.","evidence":[{"where":"Question 3","quote":"Downtime = (1 − 0.99301) × 720 = 0.00699 × 720 = 3.5 hours per month."},{"where":"Question 3","quote":"So the new availability of placing an order is 99.9975%"}]},{"id":"C4","level":"Proficient","mark":3.0,"scale":5.0,"points":3.0,"max":5.0,"reasoning":"Circuit Breaker is an appropriate pattern and is applied to the outage. However, the state names are swapped (Open and Closed), so the mechanism is partly incorrect. Tuning is mentioned (threshold, wait period) but no explicit drawback is given.","evidence":[{"where":"Question 4","quote":"When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Closed"}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"Both choices are reasonable and a cache with TTL is named for browsing. The CAP reasoning is imprecise: partition tolerance cannot be given up in a distributed system, so the payment argument is wrong. No concrete technique is named for payment (for example idempotency keys or sagas).","evidence":[{"where":"Question 5","quote":"so for payments we choose consistency and availability and give up partition tolerance"}]},{"id":"C6","level":"Proficient","mark":3.0,"scale":5.0,"points":3.0,"max":5.0,"reasoning":"Context, Decision and Consequences are all present and reasonably specific. The Consequences section lists only positive outcomes and no negative consequence (for example queue operations cost, ordering or duplicate-delivery issues, eventual notification delay).","evidence":[{"where":"Question 6","quote":"Consequences: Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"Answers are within the word limit and headings are used in order. Citation has a problem: [2] is cited but absent from the reference list, which contains only one entry.","evidence":[{"where":"Question 4","quote":"The Circuit Breaker pattern [2] would have contained the failure."}]}]}
